import React, { useState, useEffect } from "react";
import { Form, Button, ListGroup } from "react-bootstrap";
import {
  collection,
  getDocs,
  query,
  where,
  addDoc,
  Timestamp,
} from "firebase/firestore";
import { db } from "../services/firebase";

const NuovoIntervento = ({ onSelectCliente }) => {
  const [clienti, setClienti] = useState([]);
  const [queryCliente, setQueryCliente] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [mezzi, setMezzi] = useState([]);
  const [mezzoSelezionato, setMezzoSelezionato] = useState("");
  const [tipoIntervento, setTipoIntervento] = useState("");
  const [frequenza, setFrequenza] = useState("");
  const [descrizione, setDescrizione] = useState("");
  const [data, setData] = useState("");
  const [operatori, setOperatori] = useState([]);
  const [operatoreSelezionato, setOperatoreSelezionato] = useState("");

  const normalize = (str) =>
    str?.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const lista = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setClienti(lista);
      } catch (error) {
        console.error("❌ Errore nel caricamento clienti:", error.message);
      }
    };

    const fetchOperatori = async () => {
      try {
        const snapshot = await getDocs(
          query(collection(db, "UTENTI"), where("ruolo", "==", "tecnico"))
        );
        const lista = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setOperatori(lista);
      } catch (error) {
        console.error("❌ Errore nel caricamento operatori:", error.message);
      }
    };

    fetchClienti();
    fetchOperatori();
  }, []);

  useEffect(() => {
    if (normalize(queryCliente).length === 0) {
      setSuggestions([]);
      return;
    }

    const filtrati = clienti.filter((c) => {
      const campi = [c.ragioneSociale, c.codiceInterno, c.comune, c.provincia];
      return campi.some((campo) =>
        normalize(campo || "").includes(normalize(queryCliente))
      );
    });

    setSuggestions(filtrati);
  }, [queryCliente, clienti]);

  const handleClienteSelect = async (cliente) => {
    setClienteSelezionato(cliente);
    setQueryCliente(cliente.ragioneSociale);
    setSuggestions([]);
    setMezzi([]);
    if (onSelectCliente) onSelectCliente(cliente);

    if (!cliente.codiceInterno) return;

    try {
      const q = query(
        collection(db, "MEZZI"),
        where("codiceInterno", "==", cliente.codiceInterno)
      );
      const snapshot = await getDocs(q);
      const listaMezzi = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      setMezzi(listaMezzi);
    } catch (error) {
      console.error("❌ Errore nel caricamento mezzi:", error.message);
    }
  };

  const raggruppaPerProvincia = (lista) => {
    const mappa = {};
    lista.forEach((c) => {
      const chiave = `${c.comune} (${c.provincia})`;
      if (!mappa[chiave]) mappa[chiave] = [];
      mappa[chiave].push(c);
    });
    return mappa;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (
      !clienteSelezionato ||
      !mezzoSelezionato ||
      !tipoIntervento ||
      !descrizione ||
      !data ||
      !operatoreSelezionato
    ) {
      alert("⚠️ Compila tutti i campi obbligatori, incluso l'operatore");
      return;
    }

    const dataIntervento = new Date(data);

    const intervento = {
      cliente: clienteSelezionato.ragioneSociale,
      codiceInterno: clienteSelezionato.codiceInterno,
      mezzo: mezzoSelezionato,
      tipoIntervento,
      frequenza: tipoIntervento === "Manutenzione Programmata" ? frequenza : null,
      descrizione,
      dataIntervento: Timestamp.fromDate(dataIntervento),
      tecnicoAssegnatoId: operatoreSelezionato,
      terminato: false,
      statoTecnico: "assegnato",
      createdAt: Timestamp.now(),
    };

    try {
      await addDoc(collection(db, "INTERVENTI"), intervento);
      console.log("✅ Intervento salvato:", intervento);
    } catch (error) {
      console.error("❌ Errore nel salvataggio intervento:", error.message);
    }

    // Reset form
    setClienteSelezionato(null);
    setQueryCliente("");
    setSuggestions([]);
    setMezzi([]);
    setMezzoSelezionato("");
    setTipoIntervento("");
    setFrequenza("");
    setDescrizione("");
    setData("");
    setOperatoreSelezionato("");
  };

  return (
    <div className="p-3 border rounded bg-light">
      <h5 className="mb-3">🆕 Nuovo Intervento</h5>
      <Form onSubmit={handleSubmit}>
        {/* Cliente */}
        <Form.Group className="mb-3 position-relative">
          <Form.Label>Cliente</Form.Label>
          <Form.Control
            type="text"
            placeholder="🔍 Cerca per nome, codice, comune o provincia..."
            value={queryCliente}
            onChange={(e) => setQueryCliente(e.target.value)}
            autoComplete="off"
          />
          {suggestions.length > 0 && (
            <div
              style={{ maxHeight: "300px", overflowY: "auto" }}
              className="position-absolute w-100 z-3 shadow-sm bg-white"
            >
              {Object.entries(raggruppaPerProvincia(suggestions)).map(
                ([provincia, clienti]) => (
                  <div key={provincia}>
                    <strong className="bg-light px-2 py-1 d-block">
                      {provincia}
                    </strong>
                    <ListGroup>
                      {clienti.map((c) => (
                        <ListGroup.Item
                          key={c.id}
                          action
                          onClick={() => handleClienteSelect(c)}
                        >
                          {c.ragioneSociale}
                        </ListGroup.Item>
                      ))}
                    </ListGroup>
                  </div>
                )
              )}
            </div>
          )}
        </Form.Group>

        {clienteSelezionato && (
          <>
            <Form.Group className="mb-3">
              <Form.Label>Indirizzo</Form.Label>
              <Form.Control
                type="text"
                value={clienteSelezionato.indirizzo || ""}
                disabled
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Comune</Form.Label>
              <Form.Control
                type="text"
                value={clienteSelezionato.comune || ""}
                disabled
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Provincia</Form.Label>
              <Form.Control
                type="text"
                value={clienteSelezionato.provincia || ""}
                disabled
              />
            </Form.Group>
          </>
        )}

        {/* Mezzo */}
        <Form.Group className="mb-3">
          <Form.Label>Mezzo</Form.Label>
          <Form.Select
            value={mezzoSelezionato}
            onChange={(e) => setMezzoSelezionato(e.target.value)}
          >
            <option value="">Seleziona mezzo...</option>
            {mezzi.length === 0 && (
              <option disabled>🚫 Nessun mezzo disponibile</option>
            )}
            {mezzi.map((m) => (
              <option key={m.id} value={m.matricola}>
                {m.matricola} – {m.tipo || "Tipo sconosciuto"}
              </option>
            ))}
          </Form.Select>
        </Form.Group>

        {/* Tipo intervento */}
        <Form.Group className="mb-3">
          <Form.Label>Tipo Intervento</Form.Label>
          <Form.Select
            value={tipoIntervento}
            onChange={(e) => setTipoIntervento(e.target.value)}
          >
            <option value="">Seleziona tipo di intervento...</option>
            <option value="Manutenzione Programmata">🛠 Manutenzione Programmata</option>
                        <option value="Intervento Esterno">🚚 Intervento Esterno</option>
            <option value="Lavorazione Interna">🏭 Lavorazione Interna</option>
          </Form.Select>
        </Form.Group>

        {/* Frequenza (solo se manutenzione programmata) */}
        {tipoIntervento === "Manutenzione Programmata" && (
          <Form.Group className="mb-3">
            <Form.Label>Frequenza</Form.Label>
            <Form.Select
              value={frequenza}
              onChange={(e) => setFrequenza(e.target.value)}
            >
              <option value="">Seleziona frequenza...</option>
              <option value="Trimestrale">Trimestrale</option>
              <option value="Annuale">Annuale</option>
            </Form.Select>
          </Form.Group>
        )}

        {/* Descrizione */}
        <Form.Group className="mb-3">
          <Form.Label>Descrizione Intervento</Form.Label>
          <Form.Control
            as="textarea"
            rows={3}
            value={descrizione}
            onChange={(e) => setDescrizione(e.target.value)}
            placeholder="Descrivi l'intervento effettuato o previsto..."
          />
        </Form.Group>

        {/* Data */}
        <Form.Group className="mb-3">
          <Form.Label>Data Intervento</Form.Label>
          <Form.Control
            type="date"
            value={data}
            onChange={(e) => setData(e.target.value)}
          />
        </Form.Group>

        {/* Operatore */}
        <Form.Group className="mb-3">
          <Form.Label>Assegna a Operatore</Form.Label>
          <Form.Select
            value={operatoreSelezionato}
            onChange={(e) => setOperatoreSelezionato(e.target.value)}
          >
            <option value="">Seleziona operatore...</option>
            {operatori.map((op) => (
              <option key={op.id} value={op.uid}>
                {op.nome || op.email}
              </option>
            ))}
          </Form.Select>
        </Form.Group>

        {/* Submit */}
        <Button type="submit" variant="success">
          ✅ Salva Intervento
        </Button>
      </Form>
    </div>
  );
};

export default NuovoIntervento;