import React, { useState } from "react";
import NuovoIntervento from "../components/NuovoIntervento";
import MappaClienti from "../components/MappaClienti";

const DashboardAdmin = () => {
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [coordinate, setCoordinate] = useState(null);

  const handleSelect = (cliente) => {
    if (!cliente || typeof cliente !== "object") {
      setClienteSelezionato(null);
      setCoordinate(null);
      return;
    }

    setClienteSelezionato(cliente);

    const lat = parseFloat(cliente.lat);
    const lng = parseFloat(cliente.lng);

    if (!isNaN(lat) && !isNaN(lng)) {
      setCoordinate({ lat, lng });
      console.log("📍 Coordinate cliente:", { lat, lng });
    } else {
      console.warn("⚠️ Coordinate non valide:", cliente.lat, cliente.lng);
      setCoordinate(null);
    }
  };

  return (
    <div className="container-fluid">
      <h3 className="mb-4">📋 Dashboard Amministratore</h3>

      {/* 📝 Modulo intervento con autocomplete cliente integrato */}
      <div className="mb-4">
        <NuovoIntervento onSelectCliente={handleSelect} />
      </div>

      {/* 🗺️ Mappa visibile solo se coordinate disponibili */}
      {coordinate && clienteSelezionato && (
        <div className="mb-4">
          <MappaClienti
            coordinate={coordinate}
            nome={
              clienteSelezionato.ragioneSociale ||
              clienteSelezionato.Cliente ||
              "Cliente"
            }
          />
        </div>
      )}
    </div>
  );
};

export default DashboardAdmin;