import { createContext, useContext, useEffect, useState } from "react";
import { onAuthStateChanged } from "firebase/auth";
import { auth, db } from "../services/firebase";
import { collection, getDocs } from "firebase/firestore";

// ✅ Crea il contesto
const AuthContext = createContext();

// ✅ Hook per usarlo nei componenti
export const useAuth = () => useContext(AuthContext);

// ✅ Provider che avvolge l'app
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [ruolo, setRuolo] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setUser(firebaseUser);

      if (firebaseUser) {
        let ruoloTrovato = "";

        try {
          // 🔍 Tentativo via API
          const res = await fetch("/api/ruolo?uid=" + firebaseUser.uid);
          const data = await res.json();
          ruoloTrovato = data.ruolo || "";
          console.log("🔐 Ruolo da API:", ruoloTrovato);
        } catch (apiError) {
          console.warn("⚠️ API ruolo fallita, uso Firestore:", apiError);

          try {
            // 🔍 Fallback via Firestore
            const snapshot = await getDocs(collection(db, "UTENTI"));
            const utenti = snapshot.docs.map((doc) => ({
              id: doc.id,
              ...doc.data(),
            }));

            const trovato = utenti.find((u) => {
              const possibiliUID = [
                u.uid,
                u.UID,
                u.UId,
                u.Assigned_username,
                u.idUtente,
                u.id,
              ].map((v) => (typeof v === "string" ? v.trim() : ""));
              return possibiliUID.includes(firebaseUser.uid);
            });

            ruoloTrovato =
              (trovato?.ruolo || trovato?.Ruolo || trovato?.Role || "").trim();
            console.log("🔐 Ruolo da Firestore:", ruoloTrovato);
          } catch (firestoreError) {
            console.error("❌ Errore nel recupero ruolo da Firestore:", firestoreError);
          }
        }

        setRuolo(ruoloTrovato.toLowerCase());
      }

      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return (
    <AuthContext.Provider value={{ user, ruolo }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

// ✅ Esporta anche il contesto per App.jsx
export { AuthContext };