import { useContext } from "react";
import { UserContext } from "../contexts/UserContext";
import { toast } from "react-toastify";

const ListaUtenti = () => {
  const { utenti, aggiornaUtente, rimuoviUtente } = useContext(UserContext);

  const handleChange = (id, campo, valore) => {
    if (!id || !campo) return;
    aggiornaUtente(id, { [campo]: valore });
    console.log(`✏️ Campo "${campo}" aggiornato per utente ${id}`);
  };

  const handleElimina = async (id) => {
    const conferma = window.confirm("Eliminare questo utente?");
    if (conferma) {
      await rimuoviUtente(id);
      toast.info("🗑️ Utente eliminato.");
      console.log("🗑️ Utente rimosso:", id);
    }
  };

  return (
    <div className="table-responsive">
      <table className="table table-bordered align-middle">
        <thead className="table-light">
          <tr>
            <th>Nome</th>
            <th>Email</th>
            <th>Ruolo</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          {utenti.length === 0 ? (
            <tr>
              <td colSpan="4" className="text-center text-muted">
                Nessun utente presente.
              </td>
            </tr>
          ) : (
            utenti.map((utente) => (
              <tr key={utente.id}>
                <td>
                  <input
                    type="text"
                    value={utente.nome || ""}
                    onChange={(e) =>
                      handleChange(utente.id, "nome", e.target.value)
                    }
                    className="form-control"
                  />
                </td>
                <td>
                  <input
                    type="email"
                    value={utente.email || ""}
                    onChange={(e) =>
                      handleChange(utente.id, "email", e.target.value)
                    }
                    className="form-control"
                  />
                </td>
                <td>
                  <select
                    value={utente.ruolo || "guest"}
                    onChange={(e) =>
                      handleChange(utente.id, "ruolo", e.target.value)
                    }
                    className="form-select"
                  >
                    <option value="admin">Admin</option>
                    <option value="operatore">Operatore</option>
                    <option value="guest">Guest</option>
                  </select>
                </td>
                <td>
                  <button
                    className="btn btn-sm btn-danger"
                    onClick={() => handleElimina(utente.id)}
                  >
                    Elimina
                  </button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ListaUtenti;