import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase";
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from "recharts";

const StatisticheInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const snapshot = await getDocs(collection(db, "INTERVENTI"));
        const lista = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
        setInterventi(lista);
      } catch (error) {
        console.error("❌ Errore nel caricamento interventi:", error);
      }
    };
    fetchData();
  }, []);

  // 📊 Interventi per mese
  const perMese = Array.from({ length: 12 }, (_, i) => {
    const meseLabel = new Date(0, i).toLocaleString("it-IT", { month: "short" });
    const totale = interventi.filter((int) => {
      const rawDate = int.data || int.dataIntervento;
      const date = rawDate?.toDate?.() || (rawDate?.seconds ? new Date(rawDate.seconds * 1000) : null);
      return date && date.getMonth() === i;
    }).length;
    return { mese: meseLabel, totale };
  });

  // 📊 Interventi per categoria aggiornata
  const categorieUfficiali = [
    { key: "Manutenzione Programmata", label: "Manutenzioni Programmate", colore: "#0d6efd" },
    { key: "Intervento Esterno", label: "Interventi Esterni", colore: "#198754" },
    { key: "Lavorazione Interna", label: "Lavorazioni Interne", colore: "#ffc107" }
  ];

  const perCategoria = categorieUfficiali.map(({ key, label, colore }) => ({
    categoria: label,
    totale: interventi.filter((i) => i.tipoIntervento === key).length,
    colore
  }));

  // 📊 Interventi per tecnico
  const tecnici = [...new Set(interventi.map((i) => i.tecnicoAssegnato).filter(Boolean))].sort();
  const perTecnico = tecnici.map((t) => ({
    tecnico: t,
    totale: interventi.filter((i) => i.tecnicoAssegnato === t).length
  }));

  return (
    <div className="mt-5">
      <h4 className="mb-4">📈 Statistiche Interventi</h4>

      <div className="row">
        <div className="col-md-6 mb-4">
          <h5>📅 Interventi per Mese</h5>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={perMese}>
              <XAxis dataKey="mese" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="totale" fill="#0d6efd" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="col-md-6 mb-4">
          <h5>📂 Interventi per Categoria</h5>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={perCategoria}
                dataKey="totale"
                nameKey="categoria"
                cx="50%"
                cy="50%"
                outerRadius={100}
                label
              >
                {perCategoria.map((entry, i) => (
                  <Cell key={`cell-${i}`} fill={entry.colore} />
                ))}
              </Pie>
              <Legend />
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="col-md-12 mb-4">
          <h5>👷 Interventi per Tecnico</h5>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={perTecnico}>
              <XAxis dataKey="tecnico" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="totale" fill="#198754" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default StatisticheInterventi;