import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import Alert from "react-bootstrap/Alert";
import toast from "react-hot-toast";

const DettaglioIntervento = () => {
  const { id } = useParams();
  const [intervento, setIntervento] = useState(null);
  const [noteTecnico, setNoteTecnico] = useState("");
  const [statoTecnico, setStatoTecnico] = useState("");
  const [loading, setLoading] = useState(false);
  const [errore, setErrore] = useState("");

  useEffect(() => {
    const fetchIntervento = async () => {
      try {
        const ref = doc(db, "INTERVENTI", id);
        const snap = await getDoc(ref);
        if (snap.exists()) {
          const data = snap.data();
          setIntervento(data);
          setNoteTecnico(data.noteTecnico || "");
          setStatoTecnico(data.statoTecnico || "");
        } else {
          setErrore("Intervento non trovato.");
        }
      } catch (error) {
        console.error("❌ Errore caricamento:", error);
        setErrore("Errore nel caricamento dell’intervento.");
      }
    };
    fetchIntervento();
  }, [id]);

  const salvaModifiche = async () => {
    if (!statoTecnico) {
      toast.error("⚠️ Seleziona uno stato tecnico");
      return;
    }

    if ((statoTecnico === "attesa_ricambi" || statoTecnico === "conclusa") && noteTecnico.trim() === "") {
      toast.error("✏️ Inserisci le note prima di salvare");
      return;
    }

    setLoading(true);
    try {
      const ref = doc(db, "INTERVENTI", id);
      await updateDoc(ref, {
        statoTecnico,
        noteTecnico,
        updatedAt: new Date()
      });
      setIntervento(prev => ({
        ...prev,
        statoTecnico,
        noteTecnico
      }));
      toast.success("✅ Modifiche salvate");
    } catch (error) {
      console.error("❌ Errore salvataggio:", error);
      toast.error("Errore nel salvataggio");
    } finally {
      setLoading(false);
    }
  };

  if (errore) return <Alert variant="danger">{errore}</Alert>;
  if (!intervento) return <div className="p-4">⏳ Caricamento intervento...</div>;

  return (
    <div className="p-4">
      {/* Breadcrumb */}
      <nav aria-label="breadcrumb" className="mb-3">
        <ol className="breadcrumb">
          <li className="breadcrumb-item"><Link to="/">🏠 Home</Link></li>
          <li className="breadcrumb-item"><Link to="/interventi">📋 Interventi</Link></li>
          <li className="breadcrumb-item active" aria-current="page">
            {intervento?.ragioneSociale || "Dettaglio"}
          </li>
        </ol>
      </nav>

      {/* Intestazione dinamica */}
      <h3 className="mb-4">
        🔍 Intervento: <strong>{intervento?.ragioneSociale || "—"}</strong>
        <span className="text-muted ms-2">({intervento?.categoria || "—"})</span>
      </h3>

      {intervento?.dataIntervento && (
        <p className="text-muted mb-3">
          📅 Data intervento: {intervento.dataIntervento.toDate().toLocaleDateString()}
        </p>
      )}

      {/* Form di modifica */}
      <Form.Group className="mb-3">
        <Form.Label>Note Tecnico</Form.Label>
        <Form.Control
          as="textarea"
          rows={3}
          value={noteTecnico}
          onChange={(e) => setNoteTecnico(e.target.value)}
          placeholder="Note tecniche..."
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Stato Tecnico</Form.Label>
        <Form.Select value={statoTecnico} onChange={(e) => setStatoTecnico(e.target.value)}>
          <option value="">-- Seleziona stato --</option>
          <option value="accettata">✅ Accettata</option>
          <option value="attesa_ricambi">🛠️ In attesa di Ricambi</option>
          <option value="conclusa">✔️ Conclusa</option>
        </Form.Select>
      </Form.Group>

      <Button variant="primary" onClick={salvaModifiche} disabled={loading}>
        💾 Salva Modifiche
      </Button>
    </div>
  );
};

export default DettaglioIntervento;