import React from "react";

/**
 * Visualizza una data formattata in italiano.
 * Supporta sia Firebase Timestamp che oggetti Date nativi.
 * @param {Object} props
 * @param {Date|Timestamp} props.data
 */
const DateDisplay = ({ data }) => {
  let dateObj = null;

  if (!data) return <span className="text-muted">—</span>;

  if (typeof data.toDate === "function") {
    dateObj = data.toDate();
  } else if (data instanceof Date) {
    dateObj = data;
  }

  if (!dateObj || isNaN(dateObj.getTime())) {
    return <span className="text-muted">—</span>;
  }

  return <span>{dateObj.toLocaleDateString("it-IT")}</span>;
};

export default DateDisplay;