import React, { useEffect, useState } from "react";
import {
  Table,
  Badge,
  Modal,
  Button,
  Form
} from "react-bootstrap";
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  doc,
  deleteDoc,
  updateDoc
} from "firebase/firestore";
import { db } from "../services/firebase";
import toast from "react-hot-toast";
import KPIInterventi from "../components/KPIInterventi";
import StatisticheInterventi from "../components/StatisticheInterventi";
import FiltroInterventi from "../components/FiltroInterventi";
import { Calendar, dateFnsLocalizer } from "react-big-calendar";
import format from "date-fns/format";
import parse from "date-fns/parse";
import startOfWeek from "date-fns/startOfWeek";
import getDay from "date-fns/getDay";
import it from "date-fns/locale/it";
import "react-big-calendar/lib/css/react-big-calendar.css";
import { CSVLink } from "react-csv";

const locales = { it };
const localizer = dateFnsLocalizer({ format, parse, startOfWeek, getDay, locales });

const ReportInterventi = () => {
  const [interventi, setInterventi] = useState([]);
  const [manutenzioni, setManutenzioni] = useState([]);
  const [eventiCalendario, setEventiCalendario] = useState([]);
  const [filtri, setFiltri] = useState({
    tipoIntervento: "",
    cliente: "",
    tecnico: "",
    mese: ""
  });

  const [modificaAttiva, setModificaAttiva] = useState(false);
  const [interventoSelezionato, setInterventoSelezionato] = useState(null);
  const [formModifica, setFormModifica] = useState({
    descrizione: "",
    data: "",
    tipoIntervento: ""
  });

  const [modificaMPAttiva, setModificaMPAttiva] = useState(false);
  const [manutenzioneSelezionata, setManutenzioneSelezionata] = useState(null);
  const [formMP, setFormMP] = useState({
    frequenza: "",
    prossimaData: ""
  });

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, "Interventi"), (snapshot) => {
      const lista = snapshot.docs.map(doc => {
        const raw = doc.data();
        return {
          id: doc.id,
          cliente: raw.cliente || "Cliente sconosciuto",
          mezzo: raw.mezzo || "N/D",
          tipoIntervento: raw.tipoIntervento || "N/D",
          frequenza: raw.frequenza || "—",
          data: raw.data || "N/D",
          descrizione: raw.descrizione || "",
          tecnicoAssegnato: raw.tecnicoAssegnato || "Non assegnato"
        };
      });
      setInterventi(lista);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const q = query(collection(db, "ManutenzioniProgrammate"), orderBy("prossimaData", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const lista = snapshot.docs.map(doc => {
        const data = doc.data();
        const dataEvento = data.prossimaData?.toDate ? data.prossimaData.toDate() : new Date(data.prossimaData);

        return {
          id: doc.id,
          cliente: data.cliente || "Cliente sconosciuto",
          mezzo: data.mezzo || "N/D",
          frequenza: data.frequenza || "—",
          dataIntervento: data.dataIntervento || "N/D",
          prossimaData: dataEvento.toISOString().split("T")[0],
          event: {
            title: `${data.cliente} – ${data.mezzo}`,
            start: dataEvento,
            end: dataEvento,
            allDay: true,
            resource: data
          }
        };
      });

      setManutenzioni(lista);
      setEventiCalendario(lista.map(m => m.event));
    });
    return () => unsubscribe();
  }, []);

  const clientiUnici = [...new Set(interventi.map(i => i.cliente))];
  const tecniciUnici = [...new Set(interventi.map(i => i.tecnicoAssegnato))];

  const interventiFiltrati = interventi.filter(i => {
    const matchTipo = filtri.tipoIntervento ? i.tipoIntervento === filtri.tipoIntervento : true;
    const matchCliente = filtri.cliente ? i.cliente === filtri.cliente : true;
    const matchTecnico = filtri.tecnico ? i.tecnicoAssegnato === filtri.tecnico : true;
    const matchMese = filtri.mese
      ? new Date(i.data).getMonth() + 1 === parseInt(filtri.mese)
      : true;
    return matchTipo && matchCliente && matchTecnico && matchMese;
  });

  const getBadge = (tipo) => {
    switch (tipo) {
      case "Manutenzione Programmata":
        return <Badge bg="primary">🛠 {tipo}</Badge>;
      case "Intervento Esterno":
        return <Badge bg="success">🚚 {tipo}</Badge>;
      case "Lavorazione Interna":
        return <Badge bg="warning text-dark">🏭 {tipo}</Badge>;
      default:
        return <Badge bg="secondary">{tipo}</Badge>;
    }
  };

  const eliminaIntervento = async (id) => {
    if (!window.confirm("❗ Eliminare questo intervento?")) return;
    try {
      await deleteDoc(doc(db, "Interventi", id));
      toast.success("✅ Intervento eliminato");
    } catch (error) {
      toast.error("❌ Errore durante l'eliminazione");
    }
  };

  const apriModifica = (intervento) => {
    setInterventoSelezionato(intervento);
    setFormModifica({
      descrizione: intervento.descrizione || "",
      data: intervento.data || "",
      tipoIntervento: intervento.tipoIntervento || ""
    });
    setModificaAttiva(true);
  };

  const salvaModifiche = async () => {
    try {
      await updateDoc(doc(db, "Interventi", interventoSelezionato.id), {
        descrizione: formModifica.descrizione,
        data: formModifica.data,
        tipoIntervento: formModifica.tipoIntervento,
        updatedAt: new Date()
      });
      toast.success("✅ Intervento aggiornato");
      setModificaAttiva(false);
    } catch (error) {
      toast.error("❌ Errore durante la modifica");
    }
  };

  const apriModificaMP = (manutenzione) => {
    setManutenzioneSelezionata(manutenzione);
    setFormMP({
      frequenza: manutenzione.frequenza || "",
      prossimaData: manutenzione.prossimaData || ""
    });
    setModificaMPAttiva(true);
  };

  const salvaModificheMP = async () => {
    try {
      await updateDoc(doc(db, "ManutenzioniProgrammate", manutenzioneSelezionata.id), {
        frequenza: formMP.frequenza,
        prossimaData: new Date(formMP.prossimaData),
        updatedAt: new Date()
      });
      toast.success("✅ Manutenzione aggiornata");
      setModificaMPAttiva(false);
    } catch (error) {
      toast.error("❌ Errore durante la modifica");
    }
  };

  const eliminaManutenzione = async (id) => {
    if (!window.confirm("❗ Eliminare questa manutenzione programmata?")) return;
    try {
      await deleteDoc(doc(db, "ManutenzioniProgrammate", id));
      toast.success("🗑️ Manutenzione eliminata");
    } catch (error) {
      toast.error("❌ Errore durante l'eliminazione");
    }
  };

  const handleSelectEvent = (event) => {
    const { cliente, mezzo, frequenza, prossimaData } = event.resource;
    alert(`📅 Manutenzione programmata:\nCliente: ${cliente}\nMezzo: ${mezzo}\nFrequenza: ${frequenza}\nScadenza: ${prossimaData}`);
  };

  const resetFiltri = () => {
    setFiltri({
      tipoIntervento: "",
      cliente: "",
      tecnico: "",
      mese: ""
    });
  };

  const headersCSV = [
    { label: "Cliente", key: "cliente" },
    { label: "Mezzo", key: "mezzo" },
    { label: "Tipo", key: "tipoIntervento" },
    { label: "Frequenza", key: "frequenza" },
        { label: "Data", key: "data" },
    { label: "Tecnico", key: "tecnicoAssegnato" },
    { label: "Descrizione", key: "descrizione" }
  ];

  return (
    <div className="p-4">
      <h3 className="mb-4">📋 Report Interventi</h3>

      <FiltroInterventi
        filtri={filtri}
        setFiltri={setFiltri}
        clienti={clientiUnici}
        tecnici={tecniciUnici}
      />

      <div className="d-flex justify-content-between align-items-center mb-3">
        <KPIInterventi interventi={interventiFiltrati} />
        <div className="d-flex gap-2">
          <Button variant="outline-secondary" onClick={resetFiltri}>
            🔄 Reset Filtri
          </Button>
          <CSVLink
            data={interventiFiltrati}
            headers={headersCSV}
            filename="report_interventi.csv"
            className="btn btn-outline-success"
          >
            📤 Esporta CSV
          </CSVLink>
        </div>
      </div>

      <StatisticheInterventi interventi={interventiFiltrati} />

      {/* Tabella Interventi */}
      <div className="mb-5">
        <h5 className="mb-3">📑 Elenco Interventi</h5>
        <Table striped bordered hover responsive>
          <thead>
            <tr>
              <th>Cliente</th>
              <th>Mezzo</th>
              <th>Tipo</th>
              <th>Frequenza</th>
              <th>Data</th>
              <th>Tecnico Assegnato</th>
              <th>Azioni</th>
            </tr>
          </thead>
          <tbody>
            {interventiFiltrati.length === 0 ? (
              <tr>
                <td colSpan="7" className="text-center text-muted">
                  🚫 Nessun intervento registrato
                </td>
              </tr>
            ) : (
              interventiFiltrati.map((i) => (
                <tr key={i.id}>
                  <td>{i.cliente}</td>
                  <td>{i.mezzo}</td>
                  <td>{getBadge(i.tipoIntervento)}</td>
                  <td>{i.frequenza}</td>
                  <td>{i.data}</td>
                  <td>{i.tecnicoAssegnato}</td>
                  <td className="d-flex gap-2">
                    <Button variant="outline-primary" size="sm" onClick={() => apriModifica(i)}>
                      ✏️ Modifica
                    </Button>
                    <Button variant="outline-danger" size="sm" onClick={() => eliminaIntervento(i.id)}>
                      🗑 Elimina
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </div>

      {/* Tabella Manutenzioni Programmate */}
      <div className="mb-5">
        <h5 className="mb-3">📅 Scadenze Manutenzioni Programmate</h5>
        <Table striped bordered hover responsive>
          <thead>
            <tr>
              <th>Cliente</th>
              <th>Mezzo</th>
              <th>Frequenza</th>
              <th>Data Intervento</th>
              <th>Prossima Scadenza</th>
              <th>Azioni</th>
            </tr>
          </thead>
          <tbody>
            {manutenzioni.length === 0 ? (
              <tr>
                <td colSpan="6" className="text-center text-muted">
                  🚫 Nessuna manutenzione programmata
                </td>
              </tr>
            ) : (
              manutenzioni.map((m) => (
                <tr key={m.id}>
                  <td>{m.cliente}</td>
                  <td>{m.mezzo}</td>
                  <td>{m.frequenza}</td>
                  <td>{m.dataIntervento}</td>
                  <td>{m.prossimaData}</td>
                  <td className="d-flex gap-2">
                    <Button variant="outline-primary" size="sm" onClick={() => apriModificaMP(m)}>
                      ✏️ Modifica
                    </Button>
                    <Button variant="outline-danger" size="sm" onClick={() => eliminaManutenzione(m.id)}>
                      🗑 Elimina
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </div>

      {/* Calendario */}
      <div className="mb-5">
        <h5 className="mb-3">🗓 Calendario Manutenzioni Programmate</h5>
        <Calendar
          localizer={localizer}
          events={eventiCalendario}
          startAccessor="start"
          endAccessor="end"
          style={{ height: 600 }}
          onSelectEvent={handleSelectEvent}
          views={["month", "week", "day"]}
          messages={{
            month: "Mese",
            week: "Settimana",
            day: "Giorno",
            today: "Oggi",
            agenda: "Agenda"
          }}
        />
      </div>

      {/* Modale Modifica Intervento */}
      <Modal show={modificaAttiva} onHide={() => setModificaAttiva(false)}>
        <Modal.Header closeButton>
          <Modal.Title>✏️ Modifica Intervento</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Tipo Intervento</Form.Label>
              <Form.Select
                value={formModifica.tipoIntervento}
                onChange={(e) =>
                  setFormModifica({ ...formModifica, tipoIntervento: e.target.value })
                }
              >
                <option value="Manutenzione Programmata">🛠 Manutenzione Programmata</option>
                <option value="Intervento Esterno">🚚 Intervento Esterno</option>
                <option value="Lavorazione Interna">🏭 Lavorazione Interna</option>
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Data</Form.Label>
              <Form.Control
                type="date"
                value={formModifica.data}
                onChange={(e) =>
                  setFormModifica({ ...formModifica, data: e.target.value })
                }
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Descrizione</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                value={formModifica.descrizione}
                onChange={(e) =>
                  setFormModifica({ ...formModifica, descrizione: e.target.value })
                }
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setModificaAttiva(false)}>
            ❌ Annulla
          </Button>
          <Button variant="primary" onClick={salvaModifiche}>
            💾 Salva
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Modale Modifica Manutenzione */}
      <Modal show={modificaMPAttiva} onHide={() => setModificaMPAttiva(false)}>
        <Modal.Header closeButton>
          <Modal.Title>✏️ Modifica Manutenzione Programmata</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Frequenza</Form.Label>
              <Form.Select
                value={formMP.frequenza}
                onChange={(e) =>
                  setFormMP({ ...formMP, frequenza: e.target.value })
                }
              >
                <option value="Trimestrale">Trimestrale</option>
                <option value="Annuale">Annuale</option>
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Prossima Scadenza</Form.Label>
              <Form.Control
                type="date"
                value={formMP.prossimaData}
                onChange={(e) =>
                  setFormMP({ ...formMP, prossimaData: e.target.value })
                }
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setModificaMPAttiva(false)}>
            ❌ Annulla
          </Button>
          <Button variant="primary" onClick={salvaModificheMP}>
            💾 Salva
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default ReportInterventi;