import { useState, useContext } from "react";
import { auth } from "../services/firebase";
import {
  createUserWithEmailAndPassword,
  fetchSignInMethodsForEmail,
} from "firebase/auth";
import { UserContext } from "../contexts/UserContext";
import { toast } from "react-toastify";

const CreaUtente = () => {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [ruolo, setRuolo] = useState("operatore");
  const [password, setPassword] = useState("");

  const { aggiungiUtente } = useContext(UserContext);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!nome || !email || !password || !ruolo) {
      toast.error("⚠️ Compila tutti i campi.");
      return;
    }

    try {
      // 🔍 Verifica se l'email è già registrata
      const metodi = await fetchSignInMethodsForEmail(auth, email);
      if (metodi.length > 0) {
        toast.error("⚠️ Email già registrata. Usa un'altra.");
        return;
      }

      // 🔐 Crea utente in Firebase Auth
      const credenziali = await createUserWithEmailAndPassword(
        auth,
        email,
        password
      );
      const UID = credenziali.user.uid;

      // 🗂️ Salva utente in Firestore
      await aggiungiUtente({ nome, email, ruolo, UID });
      toast.success("✅ Utente creato con successo.");
      console.log("✅ Utente registrato:", { nome, email, ruolo, UID });

      // 🔄 Reset form
      setNome("");
      setEmail("");
      setPassword("");
      setRuolo("operatore");
    } catch (error) {
      console.error("❌ Errore nella creazione utente:", error);
      toast.error(error.message || "Errore nella creazione utente.");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <div className="mb-2">
        <input
          type="text"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
          placeholder="Nome"
          className="form-control"
          required
        />
      </div>
      <div className="mb-2">
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Email"
          className="form-control"
          required
        />
      </div>
      <div className="mb-2">
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password"
          className="form-control"
          required
        />
      </div>
      <div className="mb-2">
        <select
          value={ruolo}
          onChange={(e) => setRuolo(e.target.value)}
          className="form-select"
        >
          <option value="admin">Admin</option>
          <option value="operatore">Operatore</option>
          <option value="guest">Guest</option>
        </select>
      </div>
      <button type="submit" className="btn btn-primary">
        Crea Utente
      </button>
    </form>
  );
};

export default CreaUtente;