import React, { useEffect, useState } from "react";
import {
  collection,
  onSnapshot,
  updateDoc,
  doc,
  getDoc,
  Timestamp,
} from "firebase/firestore";
import { db } from "../services/firebase";
import { useAuth } from "../contexts/AuthContext";
import Table from "react-bootstrap/Table";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import toast from "react-hot-toast";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction";

const DashboardTecnico = () => {
  const { user } = useAuth();
  const [interventi, setInterventi] = useState([]);
  const [mezzi, setMezzi] = useState({});
  const [noteMap, setNoteMap] = useState({});
  const [eventiCalendario, setEventiCalendario] = useState([]);
  const [alertInterventi, setAlertInterventi] = useState([]);

  useEffect(() => {
    if (!user?.uid) return;

    const unsubscribe = onSnapshot(collection(db, "INTERVENTI"), async (snapshot) => {
      const lista = snapshot.docs
        .map((doc) => ({ id: doc.id, ...doc.data() }))
        .filter((i) => i.tecnicoAssegnatoId === user.uid);

      const mezzoIds = [...new Set(lista.map((i) => i.mezzoId).filter(Boolean))];
      const mezzoData = {};

      for (const id of mezzoIds) {
        const ref = doc(db, "MEZZI", id);
        const snap = await getDoc(ref);
        if (snap.exists()) mezzoData[id] = snap.data();
      }

      setMezzi(mezzoData);
      setInterventi(lista);

      const eventi = [];

      lista.forEach((i) => {
        if (i.dataIntervento?.toDate) {
          eventi.push({
            id: i.id + "-intervento",
            title: `${i.ragioneSociale} 🛠️ Intervento`,
            start: i.dataIntervento.toDate().toISOString().split("T")[0],
            allDay: true,
            backgroundColor: "#ffc107",
            borderColor: "#ffc107",
          });
        }

        if (
          i.categoria === "Manutenzione Programmata" &&
          i.dataIntervento?.toDate &&
          i.frequenza
        ) {
          const baseDate = i.dataIntervento.toDate();
          let prossima = new Date(baseDate);

          if (i.frequenza === "trimestrale") {
            prossima.setMonth(prossima.getMonth() + 3);
          } else if (i.frequenza === "annuale") {
            prossima.setFullYear(prossima.getFullYear() + 1);
          }

          eventi.push({
            id: i.id + "-prossima",
            title: `${i.ragioneSociale} (${i.frequenza})`,
            start: prossima.toISOString().split("T")[0],
            allDay: true,
            backgroundColor: "#0d6efd",
            borderColor: "#0d6efd",
          });
        }

        if (i.dataChiusura?.toDate) {
          eventi.push({
            id: i.id + "-chiusura",
            title: `${i.ragioneSociale} ✔️ Concluso`,
            start: i.dataChiusura.toDate().toISOString().split("T")[0],
            allDay: true,
            backgroundColor: "#198754",
            borderColor: "#198754",
          });
        }
      });

      setEventiCalendario(eventi);

      const oggi = new Date();
      const alert = lista.filter((i) => {
        if (
          i.categoria !== "Manutenzione Programmata" ||
          !i.prossimoIntervento?.toDate ||
          i.terminato
        )
          return false;

        const dataProssima = i.prossimoIntervento.toDate();
        const diff = (dataProssima - oggi) / (1000 * 60 * 60 * 24);
        return diff <= 7 && diff >= 0;
      });

      setAlertInterventi(alert);
    });

    return () => unsubscribe();
  }, [user?.uid]);

  const aggiornaStato = async (id, nuovoStato) => {
    const note = noteMap[id] || "";
    if (
      (nuovoStato === "attesa_ricambi" || nuovoStato === "conclusa") &&
      note.trim() === ""
    ) {
      toast.error("✏️ Inserisci le note prima di aggiornare lo stato");
      return;
    }

    try {
      await updateDoc(doc(db, "INTERVENTI", id), {
        statoTecnico: nuovoStato,
        noteTecnico: note,
        updatedAt: new Date(),
      });
      toast.success("✅ Stato aggiornato");
    } catch (error) {
      toast.error("❌ Errore aggiornamento");
    }
  };

  const terminaIntervento = async (id) => {
    const note = noteMap[id] || "";
    const oggi = new Date();

    try {
      await updateDoc(doc(db, "INTERVENTI", id), {
        terminato: true,
        statoTecnico: "conclusa",
        noteTecnico: note,
        dataChiusura: Timestamp.fromDate(oggi),
        updatedAt: oggi,
      });
      toast.success("✅ Intervento concluso");
    } catch (error) {
      toast.error("❌ Errore durante la chiusura");
    }
  };

  if (!user?.uid)
    return <div className="p-4 text-danger">⚠️ Utente non autenticato</div>;

  return (
    <div className="p-4">
      <h3 className="mb-3">🔧 Interventi Assegnati</h3>

      {alertInterventi.length > 0 && (
        <div className="alert alert-warning">
          <strong>🔔 Manutenzioni in scadenza:</strong>
          <ul className="mt-2">
            {alertInterventi.map((i) => (
              <li key={i.id}>
                {i.ragioneSociale} - {i.categoria} -{" "}
                {i.prossimoIntervento.toDate().toLocaleDateString()}
                <Button
                  variant="outline-success"
                  size="sm"
                  className="ms-2"
                  onClick={() => terminaIntervento(i.id)}
                >
                  ✅ Concludi
                </Button>
              </li>
            ))}
          </ul>
        </div>
      )}

      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Cliente</th>
            <th>Mezzo</th>
            <th>Categoria</th>
            <th>Data</th>
            <th>Note Tecnico</th>
            <th>Stato</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          {interventi.map((i) => {
            const mezzo = mezzi[i.mezzoId];
            return (
              <tr key={i.id}>
                <td>{i.ragioneSociale || "—"}</td>
                <td>{mezzo ? `${mezzo.marca} ${mezzo.modello}` : "—"}</td>
                <td>{i.categoria || "—"}</td>
                <td>
                  {i.dataIntervento?.toDate
                    ? i.dataIntervento.toDate().toLocaleDateString()
                    : "—"}
                </td>
                <td>
                  <Form.Control
                    as="textarea"
                    rows={2}
                    value={noteMap[i.id] || ""}
                    onChange={(e) =>
                      setNoteMap({ ...noteMap, [i.id]: e.target.value })
                    }
                    placeholder="Note tecniche..."
                  />
                </td>
                <td>{i.statoTecnico || "assegnato"}</td>
                <td className="d-flex flex-column gap-1">
                  <Button
                    variant="outline-primary"
                    size="sm"
                    onClick={() => aggiornaStato(i.id, "accettata")}
                  >
                    ✅ Accetta
                  </Button>
                  <Button
                    variant="outline-warning"
                    size="sm"
                    onClick={() => aggiornaStato(i.id, "attesa_ricambi")}
                  >
                    🛠️ In attesa ricambi
                  </Button>
                  <Button
                    variant="outline-success"
                    size="sm"
                    onClick={() => terminaIntervento(i.id)}
                  >
                    ✔️ Concludi
                  </Button>
                </td>
                            </tr>
            );
          })}
        </tbody>
      </Table>

      {/* 📅 Calendario interventi */}
      <div className="mt-5">
        <h4>📅 Manutenzioni Programmate</h4>
        <FullCalendar
          plugins={[dayGridPlugin, interactionPlugin]}
          initialView="dayGridMonth"
          events={eventiCalendario}
          height="auto"
          locale="it"
        />

        {/* 📌 Legenda */}
        <div className="mt-4">
          <h6>📌 Legenda</h6>
          <ul className="list-unstyled">
            <li className="d-flex align-items-center mb-2">
              <span className="legend-dot bg-warning me-2"></span> Intervento assegnato
            </li>
            <li className="d-flex align-items-center mb-2">
              <span className="legend-dot bg-primary me-2"></span> Manutenzione programmata
            </li>
            <li className="d-flex align-items-center mb-2">
              <span className="legend-dot bg-success me-2"></span> Intervento concluso
            </li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default DashboardTecnico;