import { createContext, useEffect, useState } from "react";
import { db } from "../services/firebase";
import {
  collection,
  addDoc,
  deleteDoc,
  updateDoc,
  doc,
  onSnapshot,
  getDocs,
  query,
  orderBy,
} from "firebase/firestore";

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const [utenti, setUtenti] = useState([]);

  // 🔄 Sync in tempo reale da Firestore con fallback
  useEffect(() => {
    const q = query(collection(db, "UTENTI"), orderBy("createdAt", "desc"));

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const lista = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setUtenti(lista);
        console.log("📦 Utenti aggiornati da Firestore (live):", lista);
      },
      async (error) => {
        console.error("❌ Errore onSnapshot, uso fallback getDocs:", error);
        try {
          const fallbackSnapshot = await getDocs(q);
          const lista = fallbackSnapshot.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
          }));
          setUtenti(lista);
          console.log("📦 Utenti caricati da Firestore (fallback):", lista);
        } catch (fallbackError) {
          console.error("❌ Errore nel fallback getDocs:", fallbackError);
        }
      }
    );

    return () => unsubscribe();
  }, []);

  // ➕ Aggiunta utente (Auth gestito altrove)
  const aggiungiUtente = async (utente) => {
    if (
      !utente ||
      typeof utente !== "object" ||
      !utente.nome ||
      !utente.email ||
      !utente.ruolo ||
      !utente.UID
    ) {
      console.warn("⚠️ Dati utente non validi:", utente);
      return;
    }

    try {
      const docRef = await addDoc(collection(db, "UTENTI"), {
        ...utente,
        createdAt: new Date(),
      });
      console.log("✅ Utente salvato in Firestore con ID:", docRef.id);
    } catch (error) {
      console.error("❌ Errore nel salvataggio utente:", error);
    }
  };

  // 🔄 Modifica utente
  const aggiornaUtente = async (id, datiAggiornati) => {
    if (!id || !datiAggiornati || typeof datiAggiornati !== "object") return;
    try {
      const ref = doc(db, "UTENTI", id);
      await updateDoc(ref, datiAggiornati);
      console.log("✏️ Utente aggiornato:", id);
    } catch (error) {
      console.error("❌ Errore nella modifica utente:", error);
    }
  };

  // 🗑️ Eliminazione utente
  const rimuoviUtente = async (id) => {
    if (!id) return;
    try {
      const ref = doc(db, "UTENTI", id);
      await deleteDoc(ref);
      console.log("🗑️ Utente eliminato:", id);
    } catch (error) {
      console.error("❌ Errore nella rimozione utente:", error);
    }
  };

  return (
    <UserContext.Provider
      value={{ utenti, aggiungiUtente, aggiornaUtente, rimuoviUtente }}
    >
      {children}
    </UserContext.Provider>
  );
};