import React, { useState, useEffect } from "react";
import { Routes, Route, useNavigate } from "react-router-dom";
import { onAuthStateChanged } from "firebase/auth";
import { collection, getDocs } from "firebase/firestore";
import { db, auth } from "./services/firebase";

import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import Sidebar from "./components/Sidebar";
import SidebarMobile from "./components/SidebarMobile";
import LogoAziendale from "./components/LogoAziendale";

import Login from "./pages/Login";
import Registrazione from "./pages/Registrazione";
import DashboardAdmin from "./pages/DashboardAdmin";
import DashboardTecnico from "./pages/DashboardTecnico";
import DashboardUtenti from "./pages/DashboardUtenti";
import RecuperoPassword from "./pages/RecuperoPassword";
import GestioneUtenti from "./pages/GestioneUtenti";
import ProfiloUtente from "./pages/ProfiloUtente";
import ReportInterventi from "./pages/ReportInterventi";
import DettaglioMezzo from "./pages/DettaglioMezzo";
import DettaglioIntervento from "./pages/DettaglioIntervento";
import ModificaIntervento from "./pages/ModificaIntervento";
import CalendarioManutenzioni from "./pages/CalendarioManutenzioni";

import ClientiTable from "./components/ClientiTable";
import MezziTable from "./components/MezziTable";
import CalendarioInterventi from "./components/CalendarioInterventi";
import CalendarioInterventiProgrammati from "./components/CalendarioInterventiProgrammati";
import StatisticheInterventi from "./components/StatisticheInterventi";
import MappaClienti from "./components/MappaClienti";

import { AuthContext } from "./contexts/AuthContext";
import { UserProvider } from "./contexts/UserContext";

function App() {
  const [utente, setUtente] = useState(null);
  const [ruoloUtente, setRuoloUtente] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setUtente(user);
      if (user) {
        try {
          const snapshot = await getDocs(collection(db, "UTENTI"));
          const utenti = snapshot.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
          }));

          const trovato = utenti.find((u) => {
            const possibiliUID = [
              u.uid,
              u.UID,
              u.UId,
              u.Assigned_username,
              u.idUtente,
              u.id,
            ].map((v) => (typeof v === "string" ? v.trim() : ""));
            return possibiliUID.includes(user.uid);
          });

          const ruolo = (
            trovato?.ruolo ||
            trovato?.Ruolo ||
            trovato?.Role ||
            ""
          )
            .trim()
            .toLowerCase();

          setRuoloUtente(ruolo);
          console.log("👤 UID Firebase:", user.uid);
          console.log("📄 Documento utente trovato:", trovato);
          console.log("👤 Ruolo utente:", ruolo);
        } catch (error) {
          console.error("❌ Errore nel recupero ruolo:", error);
          toast.error("Errore nel recupero del ruolo utente.");
        }
      }
    });

    return () => unsubscribe();
  }, []);

  const renderProtetto = (
    condizione,
    componente,
    messaggio = "⛔ Accesso negato"
  ) => (condizione ? componente : <h5 className="text-danger">{messaggio}</h5>);

  if (!utente) return <Login />;
  if (!ruoloUtente)
    return <p className="text-muted p-3">🔄 Caricamento ruolo utente...</p>;
  if (!["admin", "tecnico"].includes(ruoloUtente)) {
    return (
      <p className="text-danger p-3">
        ⚠️ Ruolo non riconosciuto: "{ruoloUtente}"
      </p>
    );
  }

  return (
    <AuthContext.Provider value={{ user: utente, ruolo: ruoloUtente }}>
      <div className="app-layout">
        {/* Sidebar */}
        <div className="d-none d-md-block">
          <Sidebar ruolo={ruoloUtente} />
        </div>
        <div className="d-md-none">
          <SidebarMobile ruolo={ruoloUtente} />
        </div>

        {/* Main Content */}
        <div className="main-content px-3 py-4">
          <ToastContainer position="top-right" autoClose={3000} />
          <Routes>
            <Route
              path="/"
              element={
                <>
                  <div className="d-flex align-items-center mb-4">
                    <LogoAziendale altezza={60} className="me-3" />
                    <h2 className="mb-0">Gestione Interventi</h2>
                  </div>
                  {ruoloUtente === "admin" && <DashboardAdmin />}
                  {ruoloUtente === "tecnico" && <DashboardTecnico />}
                </>
              }
            />
            <Route
              path="/registrazione"
              element={renderProtetto(
                ruoloUtente === "admin",
                <Registrazione />
              )}
            />
            <Route path="/recupero" element={<RecuperoPassword />} />
            <Route
              path="/utenti"
              element={renderProtetto(
                ruoloUtente === "admin",
                <UserProvider>
                  <GestioneUtenti />
                </UserProvider>
              )}
            />
            <Route
              path="/dashboard-utenti"
              element={renderProtetto(
                ruoloUtente === "admin",
                <DashboardUtenti />
              )}
            />
            <Route
              path="/admin"
              element={renderProtetto(
                ruoloUtente === "admin",
                <DashboardAdmin />
              )}
            />
            <Route path="/profilo" element={<ProfiloUtente />} />
            <Route
              path="/report"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <ReportInterventi />
              )}
            />
            <Route
              path="/mezzo/:mezzoId"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <DettaglioMezzo />
              )}
            />
            <Route
              path="/intervento/:id"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <DettaglioIntervento />
              )}
            />
            <Route
              path="/intervento/:id/modifica"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <ModificaIntervento />
              )}
            />
            <Route
              path="/clienti"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <ClientiTable />
              )}
            />
            <Route
              path="/mezzi"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <MezziTable />
              )}
            />
            <Route
              path="/calendario"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <CalendarioInterventi />
              )}
            />
            <Route
              path="/calendario-programmati"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <CalendarioInterventiProgrammati />
              )}
            />
            <Route
              path="/statistiche"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <StatisticheInterventi />
              )}
            />
            <Route
              path="/mappa-clienti"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <MappaClienti />
              )}
            />
            <Route
              path="/manutenzioni-programmate/calendario"
              element={renderProtetto(
                ["admin", "tecnico"].includes(ruoloUtente),
                <CalendarioManutenzioni />
              )}
            />
          </Routes>
        </div>
      </div>
    </AuthContext.Provider>
  );
}

export default App;