import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const ModificaIntervento = () => {
  const { interventoId } = useParams();
  const navigate = useNavigate();
  const [intervento, setIntervento] = useState(null);
  const [loading, setLoading] = useState(true);
  const [salvataggio, setSalvataggio] = useState(false);

  useEffect(() => {
    const fetchIntervento = async () => {
      try {
        const docRef = doc(db, "INTERVENTI", interventoId);
        const snapshot = await getDoc(docRef);
        if (snapshot.exists()) {
          const dati = snapshot.data();
          setIntervento({
            ...dati,
            data: dati.data?.toDate?.() || new Date()
          });
        } else {
          alert("❌ Intervento non trovato.");
          navigate("/");
        }
      } catch (error) {
        console.error("Errore nel caricamento:", error);
        alert("❌ Errore nel caricamento.");
      } finally {
        setLoading(false);
      }
    };
    fetchIntervento();
  }, [interventoId, navigate]);

  const handleChange = (campo, valore) => {
    setIntervento(prev => ({ ...prev, [campo]: valore }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!intervento.tecnico || !intervento.firmaTecnico) {
      alert("⚠️ Compila tutti i campi obbligatori.");
      return;
    }

    setSalvataggio(true);
    try {
      const docRef = doc(db, "INTERVENTI", interventoId);
      await updateDoc(docRef, {
        ...intervento,
        data: intervento.data instanceof Date ? intervento.data : new Date(intervento.data)
      });
      alert("✅ Intervento aggiornato.");
      navigate(`/intervento/${interventoId}`);
    } catch (error) {
      console.error("Errore nel salvataggio:", error);
      alert("❌ Errore nel salvataggio.");
    } finally {
      setSalvataggio(false);
    }
  };

  if (loading || !intervento) {
    return <div className="p-4">⏳ Caricamento...</div>;
  }

  return (
    <Form onSubmit={handleSubmit} className="p-4 bg-light rounded">
      <h4 className="mb-3">✏️ Modifica Intervento</h4>

      <Form.Group className="mb-2">
        <Form.Label>Tipo</Form.Label>
        <Form.Select value={intervento.tipo} onChange={(e) => handleChange("tipo", e.target.value)}>
          <option>Ordinario</option>
          <option>Straordinario</option>
          <option>Controllo</option>
        </Form.Select>
      </Form.Group>

      <Form.Group className="mb-2">
        <Form.Label>Data</Form.Label><br />
        <DatePicker
          selected={intervento.data}
          onChange={(date) => handleChange("data", date)}
          dateFormat="dd/MM/yyyy"
          className="form-control"
        />
      </Form.Group>

      <Form.Group className="mb-2">
        <Form.Label>Tecnico</Form.Label>
        <Form.Control
          value={intervento.tecnico}
          onChange={(e) => handleChange("tecnico", e.target.value)}
          required
        />
      </Form.Group>

      <Form.Group className="mb-2">
        <Form.Label>Firma Tecnico</Form.Label>
        <Form.Control
          value={intervento.firmaTecnico}
          onChange={(e) => handleChange("firmaTecnico", e.target.value)}
          required
        />
      </Form.Group>

      <Form.Group className="mb-2">
        <Form.Check
          type="checkbox"
          label="🚨 Urgente"
          checked={intervento.urgente}
          onChange={(e) => handleChange("urgente", e.target.checked)}
        />
      </Form.Group>

      <Form.Group className="mb-2">
        <Form.Label>Note</Form.Label>
        <Form.Control
          value={intervento.note}
          onChange={(e) => handleChange("note", e.target.value)}
        />
      </Form.Group>

      <Button type="submit" variant="primary" disabled={salvataggio}>
        {salvataggio ? "Salvataggio..." : "💾 Salva modifiche"}
      </Button>
    </Form>
  );
};

export default ModificaIntervento;