import React from "react";
import Card from "react-bootstrap/Card";
import Row from "react-bootstrap/Row";
import Col from "react-bootstrap/Col";

const KPIInterventi = ({ interventi = [] }) => {
  const conteggio = interventi.reduce((acc, i) => {
    acc[i.tipoIntervento] = (acc[i.tipoIntervento] || 0) + 1;
    return acc;
  }, {});

  const tipi = [
    { tipo: "Manutenzione Programmata", colore: "primary", emoji: "🛠" },
    { tipo: "Intervento Esterno", colore: "success", emoji: "🚚" },
    { tipo: "Lavorazione Interna", colore: "warning", emoji: "🏭" }
  ];

  return (
    <Row className="mb-4">
      {tipi.map(({ tipo, colore, emoji }) => (
        <Col md={4} key={tipo}>
          <Card bg={colore} text={colore === "warning" ? "dark" : "white"} className="text-center">
            <Card.Body>
              <Card.Title>{emoji} {tipo}</Card.Title>
              <h2>{conteggio[tipo] || 0}</h2>
              <small>interventi registrati</small>
            </Card.Body>
          </Card>
        </Col>
      ))}
    </Row>
  );
};

export default KPIInterventi;